  ["15364d243cea3be5"] = { "Il ⟦Stormpike Graveyard=Cimitero dei Piccatonante⟧ è stato conquistato dall'⟦Alliance=Alleanza⟧!", "." },
  ["153da91d6dd16c15"] = { "Niente da temere. Vieni.", "." },
  ["1543d731752923d7"] = { "Il ⟦Snowfall Graveyard=Cimitero di Nevealta⟧ è stato conquistato dall'⟦Alliance=Alleanza⟧!", "." },
  ["1548046a0605910d"] = { "Grazie per il tuo aiuto, {name}. Grazie a te, un'altra spedizione è arrivata sana e salva allo scavo.", "." },
  ["1548d3cfb819554c"] = { "Non ho la conoscenza che cerchi.", "." },
  ["15503e42d89dda63"] = { "Arcanum? Mi suona molto familiare.", "." },
  ["15508a981f0b3436"] = { "Conservate la vostra ira. Domate la vostra rabbia. Presto avrete tutti modo di sfogare le vostre frustrazioni.", "." },
  ["1555470d1b870ffc"] = { "Tira... e segna!", "." },
  ["155bfbddac22c705"] = { "Io... ho ferite gravi...", "." },
  ["155e3f351d5691b1"] = { "La terra è paziente e ti aspetterà finché non sarai pront<o/a>, perché sa che col tempo tutte le cose si erodono e rinascono. È il ciclo delle cose. Le montagne diventano deserti. I fiumi diventano canyon. La terra è il più ostinato e saggio di tutti gli elementi.\n\nSopra ogni cosa devi imparare la pazienza e la resistenza. La terra ora ti chiama perché sente che sei pront<o/a>. Se ci riuscirai, considera questa la tua rinascita. Dopo, non potrai mai più tornare all'ignoranza.", "." },
  ["155eb88d2da7d590"] = { "I miei complimenti allo chef!", "." },
  ["15659934c0168c4e"] = { "Il tuo dolore finirà presto!", "." },
  ["156ee335d5bf510c"] = { "Stai in guardia qui sugli altipiani, <cittadino/cittadina>. I pericoli sono tanti, tra le bestie che vagano nelle terre selvagge, i banditi assassini e la minaccia incombente degli Al'Aketh.", "." },
  ["1581be8f2f519a2e"] = { "Non farmi chiamare il mio papà per acchiapparti! Gli piace acchiappare i coniglietti con il fucile!", "." },
  ["1583d3e954e5eb2d"] = { "Spiriti dell'Acqua, vi rendo lode e vi chiedo un favore. Avete udito le suppliche di {name}, e confido che le sue intenzioni siano nobili. Vi prego, ci aiuterete?", "." },
  ["1590342b0d7a5efc"] = { "Vestire la tribù è un lavoro importante come qualsiasi altro. Cerca Tepa dentro la Thunder Bluff Armorers. Ha un talento naturale con l'ago.", "." },
  ["159192a60cfd7faf"] = { "I Sons of Arugal insorgeranno contro chiunque sfidi il potere dei Moonrage!", "." },
