  ["15a1a8bb2934db1b"] = { "Hakkar dominerà il mondo!", "." },
  ["15a7adde2c9bf4d3"] = { "Io... credo di averne visto abbastanza... è così estenuante...", "." },
  ["15b2f1e2151cf28c"] = { "Ho circa metà dei rifornimenti necessari per promuovere le truppe a unità campione.", "." },
  ["15b48efe19352148"] = { "Una volta ho sentito il vecchio Grimnur dire che aveva pescato una spada. O era un pesce spada? Maledetto Grimnur, ne ha raccontate così tante, di storie di pesca, che non ricordo più quale sia quale. Beh, perché non vai a trovarlo nella Forlorn Cavern e non ti fai dire cos'era?", "." },
  ["15bbe34440a79de7"] = { "Mmh, che domanda strana. Non molto, direi. Mia madre lo usava come talco per i neonati, contro l'irritazione da pannolino, ma a parte quello non conosco nessun altro buon uso.\r\n\nPerché lo chiedi?", "." },
  ["15bd6e2470d49e42"] = { "⟦Icebane Gauntlets=Guanti Lunghi della Rovina dei Ghiacci⟧.", "." },
  ["15c9a1326ebaca4f"] = { "Uff... mi servono una fumata e il tocco di una bella gnoma, non necessariamente in quest'ordine!\n\nHo passato mesi nella pancia di quella cosa! Che giorno è, poi? Ah, lascia perdere. Conta solo che finalmente sono fuori.\n\nIUUU-UUUH!", "." },
  ["15cc7176ac63714a"] = { "Se lo sapessi, credo che la vita qui su Zephras sarebbe molto, molto più facile. Tante delle nostre lotte e dei nostri conflitti ruotano proprio intorno a quel mistero.\r\n\nApprezzo la tua curiosità sull'argomento, ma temo che per oggi non abbia altro da dire.", "." },
  ["15d12bbc1a6230b2"] = { "Cos'è una \"fondazione di costruzione resiliente\"?", "." },
  ["15d1c5135e747c26"] = { "Ti sei <perso/persa>?", "." },
  ["15ddcadd80453181"] = { "Questa terra appartiene ai ⟦Dark Iron Dwarves=Nani Ferroscuro⟧. Preparati a vedere l'aldilà, {class}!", "." },
  ["15e55a5b8b0208f3"] = { "Incredibile! Ha funzionato! {name}, ho la tua armatura.", "." },
  ["15e560ac5d22dc38"] = { "Hai già ucciso Ran, amico mio?\n\nNemmeno gli Elfi della Notte meritano davvero la sua furia. Il suo odio brucia ancora più forte del mio, ma la sua mente non gli appartiene più. È una minaccia per tutte le creature naturali di questa foresta.", "." },
  ["15e7c7c8851ddbd7"] = { "Dirge Quikcleave di ⟦Gadgetzan=Meccania⟧ è un maestro delle arti culinarie. Per migliorare dovrai andare a cercarlo.", "." },
  ["15e9c80658ae96bb"] = { "L'anziano Morndeep passa il tempo al Ring of Law, nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧.", "." },
  ["15ec35ea3ef370b0"] = { "<Il/La> {class} che trasale è <il/la> {class} che muore. Se vuoi guardare la morte in faccia da {class}, ti insegnerò a non trasalire.", "." },
